"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Bell, Megaphone, CheckCircle, Search, Filter } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

interface Announcement {
  id: string;
  title: string;
  content: string;
  description: string;
  type: string;
  priority: string;
  isRead?: boolean;
  created_at: string;
  published_at?: string;
  archived_at?: string;
  announcement_reads?: unknown[];
}

export default function AnnouncementsPage() {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState("all"); // all, unread, important, archived
  // const supabase = createClientComponentClient();

  async function fetchAnnouncements() {
    setLoading(true);
    const { data: userData } = await supabase.auth.getUser();
    const userId = userData.user?.id;
    if (!userId) return;

    const { data: profile } = await supabase.from('employee_profiles').select('id').eq('user_id', userId).single();
    if (!profile) return;

    const { data, error } = await supabase
      .from('announcements')
      .select('*, announcement_reads(employee_id)')
      .order('published_at', { ascending: false });

    if (!error && data) {
      const mapped = data.map((a: Announcement) => ({
        ...a,
        isRead: a.announcement_reads && a.announcement_reads.length > 0,
      }));
      setAnnouncements(mapped);
    }
    setLoading(false);
  }

  useEffect(() => {
    fetchAnnouncements();
  }, []);

  const markAsRead = async (id: string) => {
    const { data: userData } = await supabase.auth.getUser();
    const userId = userData.user?.id;
    if (!userId) return;

    const { data: profile } = await supabase.from('employee_profiles').select('id').eq('user_id', userId).single();
    if (!profile) return;

    await supabase.from('announcement_reads').insert({ announcement_id: id, employee_id: profile.id });
    setAnnouncements(prev => prev.map((a: Announcement) => a.id === id ? { ...a, isRead: true } : a));
  };

  const filtered = announcements.filter((a: Announcement) => {
    if (search && !a.title.toLowerCase().includes(search.toLowerCase()) && !(a.description || "").toLowerCase().includes(search.toLowerCase())) {
      return false;
    }
    if (filterType === 'unread' && a.isRead) return false;
    if (filterType === 'important' && a.priority !== 'high') return false;
    if (filterType === 'archived' && !a.archived_at) return false;
    if (filterType !== 'archived' && a.archived_at) return false; // Hide archived by default
    return true;
  });

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12 px-4 sm:px-6 lg:px-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Announcements</h1>
          <p className="text-slate-500 text-sm mt-1">Company news, policy updates, and important notices.</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
           <div className="relative flex-1 sm:w-64">
             <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-slate-400" />
             <Input 
               placeholder="Search announcements..." 
               className="pl-9"
               value={search}
               onChange={(e) => setSearch(e.target.value)}
             />
           </div>
           <select 
             className="border rounded-md px-3 py-2 text-sm bg-white"
             value={filterType}
             onChange={(e) => setFilterType(e.target.value)}
           >
             <option value="all">All Active</option>
             <option value="unread">Unread</option>
             <option value="important">Important</option>
             <option value="archived">Archived</option>
           </select>
        </div>
      </div>

      {loading ? (
        <div className="py-20 text-center text-slate-500">Loading announcements...</div>
      ) : filtered.length === 0 ? (
        <Card className="shadow-sm border-slate-200 text-center py-20 bg-slate-50/50">
          <CardContent className="flex flex-col items-center justify-center space-y-4 pt-6">
            <div className="w-16 h-16 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center">
              <CheckCircle className="w-8 h-8" />
            </div>
            <div>
              <h3 className="font-semibold text-slate-800 text-lg">You&apos;re all caught up!</h3>
              <p className="text-slate-500 text-sm max-w-sm mx-auto mt-2">No announcements found matching your filters.</p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {filtered.map((ann) => (
            <Card key={ann.id} className={`shadow-sm transition-colors ${ann.isRead ? 'bg-white border-slate-200' : 'bg-blue-50/30 border-blue-200'}`}>
               <CardHeader className="pb-3 flex flex-row justify-between items-start">
                 <div className="space-y-1">
                   <div className="flex items-center gap-2">
                     <CardTitle className="text-lg text-slate-800">{ann.title}</CardTitle>
                     {!ann.isRead && <Badge variant="default" className="bg-blue-600">New</Badge>}
                     {ann.priority === 'high' && <Badge variant="destructive">Important</Badge>}
                   </div>
                   <p className="text-xs text-slate-500">
                     Published: {ann.published_at ? new Date(ann.published_at).toLocaleDateString() : 'N/A'} 
                     {ann.type && ` • ${ann.type}`}
                   </p>
                 </div>
               </CardHeader>
               <CardContent>
                 <p className="text-sm text-slate-700 whitespace-pre-wrap">{ann.description}</p>

                 {!ann.isRead && (
                   <div className="mt-4 flex justify-end">
                     <Button variant="outline" size="sm" onClick={() => markAsRead(ann.id)}>
                       Mark as Read
                     </Button>
                   </div>
                 )}
               </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { supabase } from "@/lib/supabase/client";
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { AlertCircle, CheckCircle2 } from "lucide-react";
import { useRouter } from "next/navigation";

export default function AttendanceCorrectionPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");
  const [formData, setFormData] = useState({ date: "", reason: "" });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.reason) {
      setError("Please fill in all required fields.");
      return;
    }
    setError("");
    setIsLoading(true);

    try {

      // const supabase = createClientComponentClient();
      const res = await supabase.from('attendance_corrections').insert(formData);

      if (res.success) {
        setSuccess(true);
        setTimeout(() => router.push("/attendance"), 1500);
      } else {
        setError("Failed to submit request.");
      }
    } catch (err) {
      setError("An unexpected error occurred.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <Card className="shadow-md border-0">
        <CardHeader>
          <CardTitle className="text-2xl font-bold text-slate-800">Request Attendance Correction</CardTitle>
          <CardDescription>
            If you forgot to check in or out, or faced technical issues, submit a correction request to HR.
          </CardDescription>
        </CardHeader>

        {success ? (
          <CardContent className="pt-6 pb-12 flex flex-col items-center justify-center space-y-4">
            <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-2">
              <CheckCircle2 className="w-8 h-8" />
            </div>
            <h3 className="text-xl font-bold text-slate-800">Request Submitted Successfully</h3>
            <p className="text-slate-500 text-center max-w-sm">Your attendance correction request has been sent to HR for approval.</p>
          </CardContent>
        ) : (
          <form onSubmit={handleSubmit}>
            <CardContent className="space-y-6">
              {error && (
                <div className="p-3 bg-red-50 text-red-600 rounded-lg flex items-center gap-2 text-sm">
                  <AlertCircle className="w-4 h-4" />
                  {error}
                </div>
              )}
              <div className="space-y-2">
                <Label htmlFor="date">Date of Correction</Label>
                <Input id="date" type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="reason">Reason for Correction</Label>
                <Input id="reason" placeholder="e.g. Forgot to check out" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} />
              </div>
            </CardContent>
            <CardFooter>
              <Button type="submit" className="w-full bg-blue-600 hover:bg-blue-700" disabled={isLoading}>
                {isLoading ? "Submitting..." : "Submit Request"}
              </Button>
            </CardFooter>
          </form>
        )}
      </Card>
    </div>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { CheckCircle2, Clock, AlertCircle } from "lucide-react";
import { useEffect, useState } from "react";
import { AttendanceService, MonthlySummary, AttendanceRecord } from "@/services/attendanceService";
import { useRouter } from "next/navigation";

export default function AttendanceHistoryPage() {
  const router = useRouter();
  const [history, setHistory] = useState<AttendanceRecord[]>([]);
  const [summary, setSummary] = useState<MonthlySummary | null>(null);

  const [currentDate, setCurrentDate] = useState(new Date());

  useEffect(() => {
    async function loadData() {
      try {
        const year = currentDate.getFullYear();
        const month = String(currentDate.getMonth() + 1).padStart(2, '0');

        // Month start and end
        const startDate = `${year}-${month}-01`;
        // rough end date for current month
        const endDate = new Date(year, currentDate.getMonth() + 1, 0).toISOString().split('T')[0];

        const records = await AttendanceService.getAttendanceHistory(startDate, endDate);
        setHistory(records?.data || []);

        const sum = await AttendanceService.getMonthlySummary(startDate, endDate);
        setSummary(sum);
      } catch (e) {
        console.error(e);
      }
    }
    loadData();
  }, [currentDate]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'present': return "text-green-600 bg-green-50 border-green-100";
      case 'late': return "text-orange-600 bg-orange-50 border-orange-100";
      case 'half_day': return "text-orange-600 bg-orange-50 border-orange-100";
      case 'absent': return "text-red-600 bg-red-50 border-red-100";
      case 'on_leave': return "text-purple-600 bg-purple-50 border-purple-100";
      case 'holiday': return "text-blue-600 bg-blue-50 border-blue-100";
      case 'weekly_off': return "text-slate-600 bg-slate-50 border-slate-100";
      case 'work_from_home': return "text-teal-600 bg-teal-50 border-teal-100";
      default: return "text-slate-600 bg-slate-50 border-slate-100";
    }
  };

  const formatTime = (isoString: string | null) => {
    if (!isoString) return "-";
    return new Date(isoString).toLocaleTimeString();
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString(undefined, {
      year: 'numeric', month: 'long', day: 'numeric'
    });
  };

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Attendance History</h1>
        <p className="text-slate-500 text-sm mt-1">Review your past attendance records and request corrections if needed.</p>
      </div>

      {summary && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
           <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-slate-500">Working Days</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{summary.totalWorkingDays}</div>
              </CardContent>
           </Card>
           <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-slate-500">Present</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-green-600">{summary.presentDays}</div>
              </CardContent>
           </Card>
           <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-slate-500">Absent/Leave</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-red-600">{summary.absentDays + summary.leaveDays}</div>
              </CardContent>
           </Card>
           <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-slate-500">Attendance %</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-blue-600">{summary.attendancePercentage}%</div>
              </CardContent>
           </Card>
        </div>
      )}

      <Card className="shadow-sm border-slate-100">
        <CardHeader className="border-b border-slate-50 pb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-lg text-slate-800">
                {currentDate.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}
              </CardTitle>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={handlePrevMonth}>Previous Month</Button>
              <Button variant="outline" size="sm" onClick={handleNextMonth}>Next Month</Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4 font-medium">Date</th>
                  <th className="px-6 py-4 font-medium">Check In</th>
                  <th className="px-6 py-4 font-medium">Check Out</th>
                  <th className="px-6 py-4 font-medium">Status</th>
                  <th className="px-6 py-4 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {history.map((record, i) => (
                  <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-800">{formatDate(record.attendance_date)}</td>
                    <td className="px-6 py-4 text-slate-600">{formatTime(record.check_in_at)}</td>
                    <td className="px-6 py-4 text-slate-600">{formatTime(record.check_out_at)}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2.5 py-1 rounded-full text-xs font-medium border ${getStatusColor(record.status)} capitalize`}>
                        {record.status.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <Button variant="outline" size="sm" className="text-xs h-8" onClick={() => router.push(`/attendance/correction?recordId=${record.id}&date=${record.attendance_date}`)}>Request Correction</Button>
                    </td>
                  </tr>
                ))}
                {history.length === 0 && (
                  <tr>
                    <td colSpan={5} className="px-6 py-8 text-center text-slate-500">
                      No attendance records found for this month.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

