"use client";

import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Calendar as CalendarIcon, Filter, List, CalendarDays, CalendarRange } from "lucide-react";
import { supabase } from "@/lib/supabase/client";
import { Button } from "@/components/ui/button";

interface CalendarEvent {
  id: string;
  title: string;
  description: string;
  start_at: string;
  end_at: string;
  event_type: string;
  all_day: boolean;
}

export default function CalendarPage() {
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<'month' | 'week' | 'list'>('month');
  const [filters, setFilters] = useState({
    holidays: true,
    my_leave: true,
    meetings: true,
    events: true,
    birthdays: true,
    anniversaries: true,
  });

  // const supabase = createClientComponentClient();

  async function fetchEvents() {
    setLoading(true);
    const { data: userData } = await supabase.auth.getUser();
    const userId = userData.user?.id;
    if (!userId) return;

    const { data: profile } = await supabase.from('employee_profiles').select('id, date_of_birth, joining_date').eq('user_id', userId).single();

    // Fetch Calendar Events
    const { data: calEvents, error } = await supabase
      .from('calendar_events')
      .select('*')
      .order('start_at', { ascending: true });

    // Fetch My Leave
    let leaveEvents: CalendarEvent[] = [];
    if (profile) {
      const { data: leaves } = await supabase
        .from('leave_requests')
        .select('*')
        .eq('employee_id', profile.id)
        .eq('status', 'approved');

      if (leaves) {
        leaveEvents = leaves.map((l: unknown) => ({
          id: `leave-${l.id}`,
          title: 'Approved Leave',
          description: l.reason,
          start_at: l.start_date,
          end_at: l.end_date,
          event_type: 'my_leave',
          all_day: true,
        }));
      }
    }

    let allEvents: unknown[] = [];
    if (calEvents) {
      allEvents = [...calEvents.map((e: CalendarEvent) => ({...e, event_type: e.event_type || 'events'}))];
    }
    allEvents = [...allEvents, ...leaveEvents];

    setEvents(allEvents);
    setLoading(false);
  }

  useEffect(() => {
    fetchEvents();
  }, []);

  const toggleFilter = (key: keyof typeof filters) => {
    setFilters(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const filteredEvents = events.filter((eventItem: CalendarEvent) => {
    if (eventItem.event_type === 'holiday' && !filters.holidays) return false;
    if (eventItem.event_type === 'my_leave' && !filters.my_leave) return false;
    if (eventItem.event_type === 'meeting' && !filters.meetings) return false;
    if (eventItem.event_type === 'event' && !filters.events) return false;
    if (eventItem.event_type === 'birthday' && !filters.birthdays) return false;
    if (eventItem.event_type === 'anniversary' && !filters.anniversaries) return false;
    return true;
  });

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12 px-4 sm:px-6 lg:px-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Company Calendar</h1>
          <p className="text-slate-500 text-sm mt-1">View holidays, leaves, and company events.</p>
        </div>
        <div className="flex gap-2">
          <Button variant={view === 'month' ? 'default' : 'outline'} size="sm" onClick={() => setView('month')}>
            <CalendarDays className="w-4 h-4 mr-2" /> Month
          </Button>
          <Button variant={view === 'week' ? 'default' : 'outline'} size="sm" onClick={() => setView('week')}>
            <CalendarRange className="w-4 h-4 mr-2" /> Week
          </Button>
          <Button variant={view === 'list' ? 'default' : 'outline'} size="sm" onClick={() => setView('list')}>
            <List className="w-4 h-4 mr-2" /> List
          </Button>
        </div>
      </div>

      <div className="flex flex-wrap gap-2">
        <BadgeFilter active={filters.holidays} onClick={() => toggleFilter('holidays')} label="Holidays" />
        <BadgeFilter active={filters.my_leave} onClick={() => toggleFilter('my_leave')} label="My Leave" />
        <BadgeFilter active={filters.meetings} onClick={() => toggleFilter('meetings')} label="Meetings" />
        <BadgeFilter active={filters.events} onClick={() => toggleFilter('events')} label="Events" />
        <BadgeFilter active={filters.birthdays} onClick={() => toggleFilter('birthdays')} label="Birthdays" />
        <BadgeFilter active={filters.anniversaries} onClick={() => toggleFilter('anniversaries')} label="Anniversaries" />
      </div>

      {loading ? (
        <div className="py-20 text-center text-slate-500">Loading events...</div>
      ) : filteredEvents.length === 0 ? (
        <Card className="shadow-sm border-slate-200 text-center py-20 bg-slate-50/50">
          <CardContent className="flex flex-col items-center justify-center space-y-4 pt-6">
            <div className="w-16 h-16 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center">
              <CalendarIcon className="w-8 h-8" />
            </div>
            <div>
              <h3 className="font-semibold text-slate-800 text-lg">No Upcoming Events</h3>
              <p className="text-slate-500 text-sm max-w-sm mx-auto mt-2">There are no events matching your current filters.</p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {/* A simple list view for now, could be expanded to grid for month/week */}
          {filteredEvents.map((evt) => (
            <Card key={evt.id} className="shadow-sm border-slate-200 p-4">
              <div className="flex gap-4 items-center">
                 <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-full flex flex-col items-center justify-center shrink-0">
                    <span className="text-xs font-semibold uppercase">{new Date(evt.start_at).toLocaleString('default', { month: 'short' })}</span>
                    <span className="text-lg font-bold leading-none">{new Date(evt.start_at).getDate()}</span>
                 </div>
                 <div>
                    <h3 className="font-semibold text-slate-800">{evt.title}</h3>
                    <p className="text-sm text-slate-500">
                      {evt.all_day ? 'All Day' : new Date(evt.start_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                      {' • '}
                      <span className="capitalize">{evt.event_type.replace('_', ' ')}</span>
                    </p>
                    {evt.description && <p className="text-sm text-slate-600 mt-1">{evt.description}</p>}
                 </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function BadgeFilter({ active, onClick, label }: { active: boolean, onClick: () => void, label: string }) {
  return (
    <button 
      onClick={onClick}
      className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${active ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
    >
      {label}
    </button>
  );
}

"use client";
import { PortalService } from "@/services/portalService";

import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { MessageSquare, AlertTriangle } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import { format } from "date-fns";

export default function ConcernsPage() {
  const [concerns, setConcerns] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    async function fetchConcerns() {
      try {
        const res = await PortalService.getConcerns();
        if (res) {
          setConcerns(res);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setIsLoading(false);
      }
    }
    fetchConcerns();
  }, []);

  const getStatusColor = (status: string) => {
    if (status === "Resolved") return "text-green-600 bg-green-50 border-green-100";
    if (status === "In Progress") return "text-orange-600 bg-orange-50 border-orange-100";
    return "text-blue-600 bg-blue-50 border-blue-100";
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">HR Concerns</h1>
          <p className="text-slate-500 text-sm mt-1">Raise confidental concerns directly with Human Resources.</p>
        </div>

          <Link href="/concerns/raise" className="inline-flex h-11 items-center justify-center rounded-xl bg-blue-600 px-6 text-base font-semibold text-white hover:bg-blue-700 shadow-sm">Raise a Concern</Link>

      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="shadow-sm border-slate-100 bg-blue-50/50">
          <CardContent className="p-6 flex gap-4">
            <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center shrink-0">
              <MessageSquare className="w-6 h-6 text-blue-600" />
            </div>
            <div>
              <h3 className="font-semibold text-slate-800">Confidentiality Assured</h3>
              <p className="text-sm text-slate-600 mt-1">All concerns raised here are strictly confidential and visible only to the Core HR team.</p>
            </div>
          </CardContent>
        </Card>

        <Card className="shadow-sm border-slate-100 bg-orange-50/50">
          <CardContent className="p-6 flex gap-4">
            <div className="w-12 h-12 rounded-full bg-orange-100 flex items-center justify-center shrink-0">
              <AlertTriangle className="w-6 h-6 text-orange-600" />
            </div>
            <div>
              <h3 className="font-semibold text-slate-800">Whistleblower Policy</h3>
              <p className="text-sm text-slate-600 mt-1">You are protected under the company whistleblower policy against any retaliation.</p>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card className="shadow-sm border-slate-100">
        <CardHeader className="border-b border-slate-50 pb-4">
          <CardTitle className="text-lg text-slate-800">My Concerns History</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4 font-medium">Ticket ID</th>
                  <th className="px-6 py-4 font-medium">Subject</th>
                  <th className="px-6 py-4 font-medium">Date Raised</th>
                  <th className="px-6 py-4 font-medium">Status</th>
                  <th className="px-6 py-4 font-medium">Visibility</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {isLoading ? (
                  <tr>
                    <td colSpan={5} className="px-6 py-8 text-center text-slate-500">Loading concerns...</td>
                  </tr>
                ) : concerns.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="px-6 py-8 text-center text-slate-500">No concerns raised.</td>
                  </tr>
                ) : concerns.map((record) => (
                  <tr key={record.id} className="hover:bg-slate-50/50 transition-colors cursor-pointer">
                    <td className="px-6 py-4 font-medium text-blue-600">{record.ticketId}</td>
                    <td className="px-6 py-4 text-slate-800 font-medium">{record.subject}</td>
                    <td className="px-6 py-4 text-slate-600">{format(new Date(record.createdAt), "d MMM yyyy")}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2.5 py-1 rounded-full text-xs font-medium border ${getStatusColor(record.status)}`}>
                        {record.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-slate-600 text-xs">
                      {record.isAnonymous ? "Anonymous" : "Public"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";
import { PortalService } from "@/services/portalService";

import { useState } from "react";
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";
import { CheckCircle2, ShieldAlert } from "lucide-react";

export default function RaiseConcernPage() {
  const router = useRouter();
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [formData, setFormData] = useState({ subject: "", description: "", isAnonymous: false });

  const handleChange = (e: React.ChangeEvent<unknown>) => {
    const value = e.target.type === 'checkbox' ? e.target.checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    if (!formData.subject || !formData.description) {
      setError("Please fill in all required fields.");
      e.preventDefault();
      return;
    }
    e.preventDefault();
    setError("");
    setIsLoading(true);

    try {
      const res = await PortalService.submitConcern(formData);
      if (!res.success) {
        setError("Failed to raise concern");
        return;
      }
      setSuccess(true);
      setTimeout(() => {
        router.push("/concerns");
      }, 2000);
    } catch (err) {
      setError("An unexpected error occurred");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <Card className="shadow-md border-0">
        <CardHeader>
          <CardTitle className="text-2xl font-bold text-slate-800">Raise a Concern</CardTitle>
        </CardHeader>

        {!success ? (
          <form onSubmit={handleSubmit}>
            <CardContent className="space-y-6">
              {error && (
                <div className="p-3 bg-red-50 border border-red-200 text-red-600 rounded-md text-sm">
                  {error}
                </div>
              )}

              <div className="bg-blue-50/50 border border-blue-100 p-4 rounded-md flex gap-3 text-sm text-slate-700">
                <ShieldAlert className="w-5 h-5 text-blue-500 shrink-0 mt-0.5" />
                <p>All concerns are treated with strict confidentiality. If you choose to submit anonymously, your name and employee ID will be hidden from the HR team.</p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="subject">Subject</Label>
                <Input id="subject" name="subject" required onChange={handleChange} placeholder="Brief summary of the issue" />
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Detailed Description</Label>
                <textarea 
                  id="description" 
                  name="description"
                  required 
                  onChange={handleChange}
                  rows={5}
                  className="w-full flex min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm"
                  placeholder="Please provide as much detail as possible..."
                ></textarea>
              </div>

              <div className="flex items-center gap-2 pt-2">
                <input 
                  type="checkbox" 
                  id="isAnonymous" 
                  name="isAnonymous" 
                  onChange={handleChange}
                  className="w-4 h-4 rounded border-slate-300 text-blue-600"
                />
                <Label htmlFor="isAnonymous" className="text-sm font-medium text-slate-700 cursor-pointer">
                  Submit this concern anonymously
                </Label>
              </div>
            </CardContent>

            <CardFooter className="bg-slate-50 border-t p-6 rounded-b-lg flex justify-end gap-3">
              <Button type="button" variant="outline" onClick={() => router.back()}>Cancel</Button>
              <Button type="submit" disabled={isLoading}>
                {isLoading ? "Submitting..." : "Submit to HR"}
              </Button>
            </CardFooter>
          </form>
        ) : (
          <CardContent className="flex flex-col items-center justify-center py-12 space-y-4">
            <CheckCircle2 className="w-16 h-16 text-green-500" />
            <h2 className="text-xl font-bold text-slate-800">Concern Submitted</h2>
            <p className="text-slate-500 text-center max-w-sm">
              Your concern has been securely transmitted to the HR department. Redirecting...
            </p>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

