"use client";

import { AttendanceService } from "@/services/attendanceService";
import { profileService } from "@/services/employee/profile.service";
import { useEffect, useState, useCallback } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { format } from "date-fns";
import { 
  CheckCircle2, Clock, MapPin, ChevronRight, Bell, Calendar, 
  Briefcase, MessageSquare, HelpCircle, User, FileText, AlertCircle, Phone, Monitor
} from "lucide-react";
import Link from "next/link";
import { toast } from "sonner"; // Assuming sonner is used for toasts, if not I'll just use alert

export default function DashboardPage() {
  const [currentTime, setCurrentTime] = useState("");
  const [isCheckedIn, setIsCheckedIn] = useState(false);
  const [checkInTime, setCheckInTime] = useState<string | null>(null);
  const [checkOutTime, setCheckOutTime] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [profileName, setProfileName] = useState("");

  useEffect(() => {
    // Current time ticker
    const timer = setInterval(() => {
      setCurrentTime(format(new Date(), "hh:mm a"));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const loadToday = useCallback(async () => {
    try {
      const today = await AttendanceService.getTodayAttendance();
      if (today && today.check_in_at) {
        setIsCheckedIn(true);
        setCheckInTime(new Date(today.check_in_at).toLocaleTimeString());
        if (today.check_out_at) {
          setCheckOutTime(new Date(today.check_out_at).toLocaleTimeString());
        }
      }
    } catch (e) {
      console.error(e);
    }
  }, []);

  useEffect(() => {
    loadToday();

    async function fetchName() {
      try {
        const p = await profileService.getEmployeeProfile();
        setProfileName(p.full_name?.split(" ")[0] || "Employee");
      } catch (e) {}
    }
    fetchName();
  }, [loadToday]);

  const getPosition = (): Promise<GeolocationPosition> => {
    return new Promise((resolve, reject) => {
      navigator.geolocation.getCurrentPosition(resolve, reject, {
        enableHighAccuracy: true,
        timeout: 5000,
        maximumAge: 0
      });
    });
  };

  const handleCheckIn = async () => {
    if (isLoading) return;
    setIsLoading(true);
    try {
      let lat: number | undefined;
      let lng: number | undefined;
      try {
        const pos = await getPosition();
        lat = pos.coords.latitude;
        lng = pos.coords.longitude;
      } catch (e) {
        console.warn("Geolocation not available or denied");
      }

      await AttendanceService.checkIn(lat, lng);
      if (toast?.success) toast.success("Checked in successfully"); else alert("Checked in successfully");
      await loadToday();
    } catch (error: unknown) {

      const err = error as unknown;
      console.error(err);
      const msg = err?.message || "Check-in failed";
      if (toast?.error) toast.error(msg); else alert(msg);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCheckOut = async () => {
    if (isLoading) return;
    setIsLoading(true);
    try {
      let lat: number | undefined;
      let lng: number | undefined;
      try {
        const pos = await getPosition();
        lat = pos.coords.latitude;
        lng = pos.coords.longitude;
      } catch (e) {
        console.warn("Geolocation not available or denied");
      }

      await AttendanceService.checkOut(lat, lng);
      if (toast?.success) toast.success("Checked out successfully"); else alert("Checked out successfully");
      await loadToday();
    } catch (error: unknown) {

      const err = error as unknown;
      console.error(err);
      const msg = err?.message || "Check-out failed";
      if (toast?.error) toast.error(msg); else alert(msg);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12">
      {/* Mobile Top Welcome (Hidden on desktop as it&apos;s in the header) */}
      <div className="md:hidden flex items-center justify-between mb-2">
        <div>
          <h1 className="text-xl font-bold text-slate-900 leading-tight">Good Morning,<br/>{profileName || "Employee"}! 👋</h1>
          <p className="text-xs text-slate-500 mt-1">Have a productive day ahead.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Mobile-first Action Card (Left column on Desktop) */}
        <div className="lg:col-span-4 space-y-6">

          <Card className="shadow-sm border-slate-100 overflow-hidden relative">
            <div className="absolute top-0 w-full h-1 bg-blue-600"></div>
            <CardContent className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-semibold text-slate-800 text-sm">Today's Status</h3>
                <span className="text-xs text-blue-600 font-medium cursor-pointer hover:underline">View Details</span>
              </div>

              {!isCheckedIn ? (
                <Button disabled={isLoading} onClick={handleCheckIn} className="w-full h-12 text-base font-semibold shadow-md gap-2 rounded-xl mb-4">
                  <CheckCircle2 className="w-5 h-5" /> {isLoading ? "Checking in..." : "Check In"}
                </Button>
              ) : (
                <div className="space-y-3 mb-4">
                  <div className="w-full h-12 bg-green-50 text-green-700 font-semibold flex items-center justify-center rounded-xl border border-green-200">
                    <div className="w-2 h-2 rounded-full bg-green-500 mr-2"></div>
                    Checked in at {checkInTime}
                  </div>
                  {!checkOutTime ? (
                    <Button disabled={isLoading} variant="outline" onClick={handleCheckOut} className="w-full h-12 text-base font-semibold text-slate-700 rounded-xl gap-2">
                      <MapPin className="w-4 h-4" /> {isLoading ? "Checking out..." : "Check Out"}
                    </Button>
                  ) : (
                    <div className="w-full h-12 bg-slate-50 text-slate-700 font-semibold flex items-center justify-center rounded-xl border border-slate-200">
                      Checked out at {checkOutTime}
                    </div>
                  )}
                </div>
              )}

              <p className="text-center text-[10px] text-slate-400 font-medium">
                {!isCheckedIn ? "Not Checked In Yet" : (!checkOutTime ? "Currently working..." : "Work day completed")}
              </p>
            </CardContent>
          </Card>

          <div className="grid grid-cols-2 gap-4">
            <Card className="shadow-sm border-slate-100">
              <CardContent className="p-4 flex gap-3 items-center">
                <div className="w-8 h-8 rounded-full bg-blue-50 flex items-center justify-center shrink-0">
                  <Clock className="w-4 h-4 text-blue-500" />
                </div>
                <div>
                  <p className="text-[10px] text-slate-500 font-medium uppercase tracking-wider">Working Hours</p>
                  <p className="text-sm font-bold text-slate-800 leading-tight">02h 35m</p>
                  <p className="text-[10px] text-slate-400">Today</p>
                </div>
              </CardContent>
            </Card>
            <Card className="shadow-sm border-slate-100">
              <CardContent className="p-4 flex gap-3 items-center">
                <div className="w-8 h-8 rounded-full bg-purple-50 flex items-center justify-center shrink-0">
                  <Briefcase className="w-4 h-4 text-purple-500" />
                </div>
                <div>
                  <p className="text-[10px] text-slate-500 font-medium uppercase tracking-wider">Leave Balance</p>
                  <p className="text-sm font-bold text-slate-800 leading-tight">12 Days</p>
                  <p className="text-[10px] text-slate-400">Available</p>
                </div>
              </CardContent>
            </Card>
          </div>

          <Card className="shadow-sm border-slate-100">
            <CardHeader className="p-4 pb-0 flex flex-row items-center justify-between">
              <CardTitle className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Upcoming Leave</CardTitle>
              <Link href="/leave" className="text-[10px] text-blue-600 font-medium hover:underline">View All</Link>
            </CardHeader>
            <CardContent className="p-4">
              <div className="flex justify-between items-center border border-slate-100 p-3 rounded-lg bg-slate-50/50">
                <div className="flex gap-3">
                  <div className="w-8 h-8 rounded-md bg-white border border-slate-100 flex items-center justify-center shrink-0">
                    <Calendar className="w-4 h-4 text-blue-600" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-800">Family Vacation</p>
                    <p className="text-[10px] text-slate-500 mt-0.5">12 May - 16 May 2025</p>
                  </div>
                </div>
                <span className="px-2 py-0.5 bg-green-50 text-green-600 text-[10px] font-medium rounded-full border border-green-100">Approved</span>
              </div>
            </CardContent>
          </Card>

          <div className="grid grid-cols-2 gap-4">
            <Link href="/attendance">
              <Card className="shadow-sm border-slate-100 hover:border-blue-600/40 transition-colors">
                <CardContent className="p-4 flex gap-3 items-center">
                  <div className="w-10 h-10 rounded-xl bg-green-100 flex items-center justify-center shrink-0">
                    <CheckCircle2 className="w-5 h-5 text-green-600" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-800">Attendance</p>
                    <p className="text-[10px] text-slate-500">View history</p>
                  </div>
                </CardContent>
              </Card>
            </Link>
            <Link href="/leave/apply">
              <Card className="shadow-sm border-slate-100 hover:border-blue-600/40 transition-colors">
                <CardContent className="p-4 flex gap-3 items-center">
                  <div className="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center shrink-0">
                    <Briefcase className="w-5 h-5 text-blue-600" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-800">Apply Leave</p>
                    <p className="text-[10px] text-slate-500">Submit request</p>
                  </div>
                </CardContent>
              </Card>
            </Link>
            <Link href="/concerns/raise">
              <Card className="shadow-sm border-slate-100 hover:border-blue-600/40 transition-colors">
                <CardContent className="p-4 flex gap-3 items-center">
                  <div className="w-10 h-10 rounded-xl bg-purple-100 flex items-center justify-center shrink-0">
                    <MessageSquare className="w-5 h-5 text-purple-600" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-800 leading-tight">Raise a Concern</p>
                    <p className="text-[10px] text-slate-500">Get help</p>
                  </div>
                </CardContent>
              </Card>
            </Link>
            <Link href="/profile">
              <Card className="shadow-sm border-slate-100 hover:border-blue-600/40 transition-colors">
                <CardContent className="p-4 flex gap-3 items-center">
                  <div className="w-10 h-10 rounded-xl bg-orange-100 flex items-center justify-center shrink-0">
                    <User className="w-5 h-5 text-orange-600" />
                  </div>
