  useEffect(() => {
    async function loadData() {
      try {
        const [ticketData, messagesData] = await Promise.all([
          helpService.getHelpRequestById(resolvedParams.id),
          helpService.getHelpRequestMessages(resolvedParams.id)
        ]);
