    loadData();
  }, [resolvedParams.id]);

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replyText.trim() && !file) return;
    setIsReplying(true);
    try {
      let finalMessage = replyText;
      if (file) {
        const url = await helpService.uploadAttachment(file, resolvedParams.id);
        finalMessage += `\n\n[Attachment: ${file.name}](${url})`;
      }
      const newMessage = await helpService.replyToHelpRequest(resolvedParams.id, finalMessage);
      setMessages([...messages, newMessage]);
      setReplyText("");
      setFile(null);
    } catch (err) {
      console.error(err);
    } finally {
      setIsReplying(false);
    }
  };

  const handleClose = async () => {
    if (confirm("Are you sure you want to close this help request?")) {
      try {
        const updated = await helpService.closeHelpRequest(resolvedParams.id);
        setTicket(updated);
      } catch (err) {
        console.error(err);
      }
    }
  };

  if (isLoading) {
    return <div className="p-8 text-center">Loading ticket details...</div>;
  }

  if (!ticket) {
    return <div className="p-8 text-center text-red-500">Ticket not found.</div>;
  }

  const isClosed = ticket.status === 'resolved' || ticket.status === 'closed';

  return (
    <div className="max-w-4xl mx-auto space-y-6 pb-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <button onClick={() => router.push("/help")} className="text-blue-600 hover:underline text-sm mb-2">&larr; Back to Help</button>
          <h1 className="text-2xl font-bold text-slate-900">{ticket.subject}</h1>
          <p className="text-slate-500 text-sm mt-1">Ticket {ticket.help_id} • {ticket.category} • {format(new Date(ticket.created_at), "PPP p")}</p>
        </div>
        <div className="flex items-center gap-3">
          <span className="px-3 py-1 rounded-full text-sm font-medium border capitalize bg-slate-100">
            {ticket.status.replace("_", " ")}
          </span>
          {!isClosed && (
            <Button variant="outline" onClick={handleClose}>
              Mark as Resolved
            </Button>
          )}
        </div>
      </div>

      <Card>
        <CardHeader className="bg-slate-50 border-b">
          <CardTitle className="text-lg">Description</CardTitle>
        </CardHeader>
        <CardContent className="p-6 whitespace-pre-wrap text-slate-700">
          {ticket.description}
        </CardContent>
      </Card>

      <div className="space-y-4">
        <h3 className="text-lg font-semibold text-slate-800">Messages</h3>
        {messages.length === 0 ? (
          <div className="text-center py-8 bg-slate-50 rounded-lg border border-dashed border-slate-200 text-slate-500">
            No messages yet.
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((msg) => (
              <Card key={msg.id} className={msg.sender_id === ticket.employee_id ? "ml-12 border-blue-100 bg-blue-50/30" : "mr-12"}>
                <CardContent className="p-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="font-semibold text-sm">
                      {msg.sender_id === ticket.employee_id ? "You" : "Support Agent"}
                    </span>
                    <span className="text-xs text-slate-500">
                      {format(new Date(msg.created_at), "PPP p")}
                    </span>
                  </div>
                  <div className="text-slate-700 whitespace-pre-wrap text-sm">
                    {msg.message}
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {!isClosed && (
          <Card className="mt-6">
            <form onSubmit={handleReply}>
              <CardContent className="p-4 space-y-4">
                <textarea
                  value={replyText}
                  onChange={(e) => setReplyText(e.target.value)}
                  placeholder="Type your reply here..."
                  className="w-full flex min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                ></textarea>
                <div className="flex items-center gap-4">
                  <Input type="file" id="attachment" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
                   <label htmlFor="attachment" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer flex items-center gap-2 text-slate-600 hover:text-blue-600 border px-3 py-2 rounded-md">
                    <Paperclip className="w-4 h-4" />
                    {file ? file.name : "Attach File"}
                  </label>
                  {file && (
                    <button type="button" onClick={() => setFile(null)} className="text-red-500 text-xs hover:underline">
                      Remove
                    </button>
                  )}
                </div>
              </CardContent>
              <CardFooter className="bg-slate-50 border-t p-4 flex justify-end">
                <Button type="submit" disabled={isReplying || (!replyText.trim() && !file)}>
                  {isReplying ? "Sending..." : "Send Reply"} <Send className="w-4 h-4 ml-2" />
                </Button>
              </CardFooter>
            </form>
          </Card>
        )}
        {isClosed && (
          <div className="flex items-center gap-2 text-amber-600 bg-amber-50 p-4 rounded-lg border border-amber-100">
            <AlertCircle className="w-5 h-5" />
            <p className="text-sm font-medium">This ticket has been closed and cannot accept new replies.</p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";
import { helpService } from "@/services/employee/help.service";

import { useState, useEffect, Suspense } from "react";
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { useRouter, useSearchParams } from "next/navigation";
import { CheckCircle2, Laptop } from "lucide-react";

function AskForHelpForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [formData, setFormData] = useState({ category: searchParams.get("category") || "", subject: "", description: "", priority: "medium" });

  const handleChange = (e: React.ChangeEvent<unknown>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.subject || !formData.category || !formData.description) {
      setError("Please fill in all required fields.");
      return;
    }
    setError("");
    setIsLoading(true);

    try {
      await helpService.submitHelpRequest(formData);
      setSuccess(true);
      setTimeout(() => {
        router.push("/help");
      }, 2000);
    } catch (err: unknown) {

      const e = err as unknown;
      setError(e.message || "An unexpected error occurred");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Card className="shadow-md border-0">
      <CardHeader>
        <CardTitle className="text-2xl font-bold text-slate-800">Ask for Help</CardTitle>
      </CardHeader>

      {!success ? (
        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-6">
            {error && (
              <div className="p-3 bg-red-50 border border-red-200 text-red-600 rounded-md text-sm">
                {error}
              </div>
            )}

            <div className="bg-slate-50 border border-slate-100 p-4 rounded-md flex gap-3 text-sm text-slate-700">
              <Laptop className="w-5 h-5 text-slate-500 shrink-0 mt-0.5" />
              <p>Use this form for general IT, admin, or HR support. For serious issues, please use the <a href="/concerns" className="text-blue-600 font-medium hover:underline">Raise a Concern</a> feature instead.</p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Help Category</Label>
              <select id="category" name="category" value={formData.category} onChange={handleChange} className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background" required>
                <option value="">Select a category...</option>
                <option value="HR Help">HR Help</option>
                <option value="IT Help">IT Help</option>
                <option value="Office Help">Office Help</option>
                <option value="Manager Assistance">Manager Assistance</option>
                <option value="Payroll Help">Payroll Help</option>
                <option value="General Help">General Help</option>
              </select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="priority">Priority</Label>
              <select id="priority" name="priority" value={formData.priority} onChange={handleChange} className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background" required>
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="subject">Subject</Label>
              <Input id="subject" name="subject" value={formData.subject} required onChange={handleChange} placeholder="Brief summary of what you need help with" />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Message</Label>
              <textarea 
                id="description" 
                name="description"
                value={formData.description}
                required 
                onChange={handleChange}
                rows={5}
                className="w-full flex min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm"
                placeholder="Please describe your issue or request in detail..."
              ></textarea>
            </div>
          </CardContent>

          <CardFooter className="bg-slate-50 border-t p-6 rounded-b-lg flex justify-end gap-3">
            <Button type="button" variant="outline" onClick={() => router.back()}>Cancel</Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading ? "Submitting..." : "Submit Request"}
            </Button>
          </CardFooter>
        </form>
      ) : (
        <CardContent className="flex flex-col items-center justify-center py-12 space-y-4">
          <CheckCircle2 className="w-16 h-16 text-green-500" />
          <h2 className="text-xl font-bold text-slate-800">Request Submitted</h2>
          <p className="text-slate-500 text-center max-w-sm">
            Your help request has been assigned to the support team. Redirecting...
          </p>
        </CardContent>
      )}
    </Card>
  );
}

export default function AskForHelpPage() {
  return (
    <div className="max-w-2xl mx-auto py-8">
      <Suspense fallback={<div>Loading form...</div>}>
        <AskForHelpForm />
      </Suspense>
    </div>
